/** Parsed DIR for one source module. */
export type DirParsed = {
    /** The parsed tree, indexed with its structural parents. */
    readonly tree: Tree;
    /** The parsed physical files. */
    readonly files: ReadonlyArray<DirParsedFile>;
    /** Stable anchor expression for diagnostics. */
    readonly anchorExpression: LocalNodeId;
};

export const DirParsed = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: DirParsed): void {
        encodeDirParsed(writer, value);
    },

    /** Decode one DirParsed. */
    decode(reader: BinaryReader): DirParsed {
        return decodeDirParsed(reader);
    },

    /** Return this value as JSON. */
    toJson(value: DirParsed): Json {
        return toJsonDirParsed(value);
    },

    /** Return one DirParsed from one JSON value. */
    fromJson(value: Json): DirParsed {
        return fromJsonDirParsed(value);
    },
};

/** Encode one DirParsed. */
export function encodeDirParsed(writer: BinaryWriter, value: DirParsed): void {
    encodeTree(writer, value.tree);
    writer.writeUnsigned(value.files.length);
    for (const item1 of value.files) {
        encodeDirParsedFile(writer, item1);
    }
    encodeLocalNodeId(writer, value.anchorExpression);
}

/** Decode one DirParsed. */
export function decodeDirParsed(reader: BinaryReader): DirParsed {
    const tree = decodeTree(reader);
    const files = (() => { const length1 = reader.readNumber(); const items1: Array<DirParsedFile> = []; for (let index = 0; index < length1; index += 1) { items1.push(decodeDirParsedFile(reader)); } return items1; })();
    const anchorExpression = decodeLocalNodeId(reader);

    return {
        tree,
        files,
        anchorExpression,
    };
}

/** Return one JSON value for one DirParsed. */
export function toJsonDirParsed(value: DirParsed): Json {
    return {
        tree: toJsonTree(value.tree),
        files: value.files.map((item0) => toJsonDirParsedFile(item0)),
        anchorExpression: toJsonLocalNodeId(value.anchorExpression),
    };
}

/** Return one DirParsed from one JSON value. */
export function fromJsonDirParsed(value: Json): DirParsed {
    const object = jsonObject(value);

    return {
        tree: fromJsonTree(jsonField(object, "tree")),
        files: jsonArray(jsonField(object, "files")).map((item0) => fromJsonDirParsedFile(item0)),
        anchorExpression: fromJsonLocalNodeId(jsonField(object, "anchorExpression")),
    };
}

/** Parser output for one physical file in a canonical module. */
export type DirParsedFile = {
    /** The source file id. */
    readonly fileId: FileId;
    /** The condition aliases attached to this file. */
    readonly aliases: ReadonlyArray<string>;
    /** The top-level expressions parsed from this file. */
    readonly roots: ReadonlyArray<LocalNodeId>;
    /** The semantic source tokens. */
    readonly tokens: ReadonlyArray<TokenRecord>;
    /** The retained source comments. */
    readonly comments: ReadonlyArray<Comment>;
    /** Stable anchor expression for diagnostics in this file. */
    readonly anchorExpression: LocalNodeId;
};

export const DirParsedFile = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: DirParsedFile): void {
        encodeDirParsedFile(writer, value);
    },

    /** Decode one DirParsedFile. */
    decode(reader: BinaryReader): DirParsedFile {
        return decodeDirParsedFile(reader);
    },

    /** Return this value as JSON. */
    toJson(value: DirParsedFile): Json {
        return toJsonDirParsedFile(value);
    },

    /** Return one DirParsedFile from one JSON value. */
    fromJson(value: Json): DirParsedFile {
        return fromJsonDirParsedFile(value);
    },
};

/** Encode one DirParsedFile. */
export function encodeDirParsedFile(writer: BinaryWriter, value: DirParsedFile): void {
    encodeFileId(writer, value.fileId);
    writer.writeUnsigned(value.aliases.length);
    for (const item1 of value.aliases) {
        writer.writeString(item1);
    }
    writer.writeUnsigned(value.roots.length);
    for (const item2 of value.roots) {
        encodeLocalNodeId(writer, item2);
    }
    writer.writeUnsigned(value.tokens.length);
    for (const item3 of value.tokens) {
        encodeTokenRecord(writer, item3);
    }
    writer.writeUnsigned(value.comments.length);
    for (const item4 of value.comments) {
        encodeComment(writer, item4);
    }
    encodeLocalNodeId(writer, value.anchorExpression);
}

/** Decode one DirParsedFile. */
export function decodeDirParsedFile(reader: BinaryReader): DirParsedFile {
    const fileId = decodeFileId(reader);
    const aliases = (() => { const length1 = reader.readNumber(); const items1: Array<string> = []; for (let index = 0; index < length1; index += 1) { items1.push(reader.readString()); } return items1; })();
    const roots = (() => { const length2 = reader.readNumber(); const items2: Array<LocalNodeId> = []; for (let index = 0; index < length2; index += 1) { items2.push(decodeLocalNodeId(reader)); } return items2; })();
    const tokens = (() => { const length3 = reader.readNumber(); const items3: Array<TokenRecord> = []; for (let index = 0; index < length3; index += 1) { items3.push(decodeTokenRecord(reader)); } return items3; })();
    const comments = (() => { const length4 = reader.readNumber(); const items4: Array<Comment> = []; for (let index = 0; index < length4; index += 1) { items4.push(decodeComment(reader)); } return items4; })();
    const anchorExpression = decodeLocalNodeId(reader);

    return {
        fileId,
        aliases,
        roots,
        tokens,
        comments,
        anchorExpression,
    };
}

/** Return one JSON value for one DirParsedFile. */
export function toJsonDirParsedFile(value: DirParsedFile): Json {
    return {
        fileId: toJsonFileId(value.fileId),
        aliases: value.aliases.map((item0) => item0),
        roots: value.roots.map((item0) => toJsonLocalNodeId(item0)),
        tokens: value.tokens.map((item0) => toJsonTokenRecord(item0)),
        comments: value.comments.map((item0) => toJsonComment(item0)),
        anchorExpression: toJsonLocalNodeId(value.anchorExpression),
    };
}

/** Return one DirParsedFile from one JSON value. */
export function fromJsonDirParsedFile(value: Json): DirParsedFile {
    const object = jsonObject(value);

    return {
        fileId: fromJsonFileId(jsonField(object, "fileId")),
        aliases: jsonArray(jsonField(object, "aliases")).map((item0) => jsonString(item0)),
        roots: jsonArray(jsonField(object, "roots")).map((item0) => fromJsonLocalNodeId(item0)),
        tokens: jsonArray(jsonField(object, "tokens")).map((item0) => fromJsonTokenRecord(item0)),
        comments: jsonArray(jsonField(object, "comments")).map((item0) => fromJsonComment(item0)),
        anchorExpression: fromJsonLocalNodeId(jsonField(object, "anchorExpression")),
    };
}

